const cfg = $input.item.json;
const productName = cfg.product_name;

const queries = {
  specs: `${productName} official specifications`,
  independent: `${productName} independent expert review`,
  owner: `${productName} owner reviews customer experience`,
  alternatives: `${productName} alternatives comparison vs`
};

const searches = {};
for (const [key, q] of Object.entries(queries)) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://searxng:8080/search',
      qs: { format: 'json', language: 'en', q },
      json: true
    });
    searches[key] = (res.results || []).slice(0, 6).map(r => ({ title: r.title, url: r.url, content: r.content }));
  } catch (e) {
    searches[key] = [];
  }
}

return [{
  json: {
    ...cfg,
    searches
  }
}];

const cfg = $input.item.json;

const choose_system_prompt = `You are a research assistant choosing which real search results are worth reading in full to research a product.

You will be given search results grouped into 4 categories:
- specs: official manufacturer specifications
- independent: an independent/expert review (must NOT be the manufacturer's own website)
- owner: owner/customer reviews
- alternatives: competing products

Rules:
1. For 'independent', you MUST pick a URL whose domain is different from the official manufacturer's domain (the manufacturer's domain will be visible in the 'specs' results).
2. For each category, pick the single best, most relevant, most trustworthy URL from the results ACTUALLY PROVIDED - never invent a URL not present in the given results.
3. NEVER pick a URL ending in .pdf, or any URL that is obviously a PDF/binary document - those cannot be read as text. Always prefer a normal HTML web page.
4. If a category truly has no usable (non-PDF) results, omit it from your picks.
5. For 'specs', 'owner' and 'alternatives', you may pick up to 2 URLs (a primary and a backup) in case one fails to load. For 'independent', pick up to 3 URLs (a primary and two backups) - independent review sites are especially prone to membership walls, paywalls and JS-only content that leaves no usable text once fetched, so give yourself more chances to land on one that actually works.
6. You MUST include at least one pick for EACH of the four categories (specs, independent, owner, alternatives) as long as that category has at least one non-PDF result available. Do not skip a category just because another category seems more interesting.
7. Output JSON only: {"picks": [{"category": "...", "url": "...", "why": "..."}]}`;

const choose_user_prompt = `Product: ${cfg.product_name} (${cfg.brand}, ${cfg.category})

SEARCH RESULTS BY CATEGORY:
${JSON.stringify(cfg.searches)}

Pick the URLs worth reading in full.`;

const choose_schema = {"type": "object", "properties": {"picks": {"type": "array", "items": {"type": "object", "properties": {"category": {"type": "string", "enum": ["specs", "independent", "owner", "alternatives"]}, "url": {"type": "string"}, "why": {"type": "string"}}, "required": ["category", "url", "why"]}}}, "required": ["picks"]};

return [{
  json: {
    ...cfg,
    choose_system_prompt: choose_system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(choose_schema)}`,
    choose_user_prompt,
    choose_schema
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';
let parsed = null, parseError = null;
try { parsed = JSON.parse(raw); } catch (e) { parseError = e.message; }

const prep = $('Prepare Choose Prompt').item.json;
let _researchRetryCount = 0;
try { _researchRetryCount = $('Retry Choose Sources').item.json._researchRetryCount || 0; } catch (e) { _researchRetryCount = 0; }

return [{
  json: {
    ollama_base_url: prep.ollama_base_url,
    research_model: prep.research_model,
    writer_model: prep.writer_model,
    qa_model: prep.qa_model,
    qa_min_confidence: prep.qa_min_confidence,
    product_name: prep.product_name,
    brand: prep.brand,
    category: prep.category,
    picks: (parsed && parsed.picks) || [],
    _chooseParseError: parseError,
    _researchRetryCount
  }
}];

const item = $input.item.json;
const picks = item.picks || [];
const pages = [];
const scrapedImages = [];
const productName = (item.product_name || '').toLowerCase();

function extractRelevantWindow(text, keyword, windowSize) {
  if (!keyword) return text.slice(0, windowSize);
  const lower = text.toLowerCase();
  const idx = lower.indexOf(keyword);
  if (idx === -1) return text.slice(0, windowSize);
  const start = Math.max(0, idx - Math.floor(windowSize * 0.25));
  return text.slice(start, start + windowSize);
}

// n8n's Code node sandbox has no global URL constructor - relative image URLs are
// resolved by hand, same pattern as Stage 3a's "Source Manufacturer Images".
function resolveUrl(url, base) {
  if (!url) return null;
  url = String(url).trim();
  if (/^https?:\/\//i.test(url)) return url;
  const schemeMatch = String(base).match(/^([a-zA-Z][a-zA-Z0-9+.-]*:)/);
  const scheme = schemeMatch ? schemeMatch[1] : 'https:';
  if (/^\/\//.test(url)) return scheme + url;
  const originMatch = String(base).match(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^/]+/);
  const origin = originMatch ? originMatch[0] : '';
  if (url.startsWith('/')) return origin + url;
  const basePath = String(base).replace(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^/]+/, '').replace(/[^/]*$/, '');
  return origin + basePath + url;
}

function hostnameOf(url) {
  try { const m = String(url).match(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/(?:[^@/]+@)?([^/:?#]+)/); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; } catch (e) { return ''; }
}

const brandToken = (item.brand || '').toLowerCase().replace(/[^a-z0-9]/g, '');

// Every "specs"/"independent" source Choose Sources already picked gets fetched
// here anyway for research text - pulling og:image/twitter:image from the SAME
// fetch is free (no extra HTTP round trip) and gives a real photo of the actual
// product from a page a human editor picked, not a keyword search guess.
// Tagged by domain, same discipline as Stage 3a's manufacturer scrape: a
// specs-category source hosted on the brand's own domain is 'manufacturer_scrape',
// anything else (a third-party review/retailer site actually publishing its own
// photography, e.g. rtings/theverge/gizmodo) is 'editorial_scrape' - real risk
// difference (someone else's copyrighted editorial photo vs. a brand's own press
// asset), tracked so it can be reviewed/licensed or dropped before real launch,
// not silently treated the same as either manufacturer or CC-licensed Openverse.
function extractImages(html, baseUrl) {
  const htmlStr = String(html);
  const found = [];
  const seen = new Set();
  function add(url, tag) {
    const resolved = resolveUrl(url, baseUrl);
    if (!resolved || !/^https?:\/\//i.test(resolved) || seen.has(resolved)) return;
    // Same filter as Stage 3a's manufacturer scrape - confirmed live: Samsung's own
    // product page's twitter:image was its generic sitewide logo asset
    // ("logo-square-letter.png"), which outranked several real product photos from
    // editorial sources purely because manufacturer_scrape is checked first.
    if (/logo|favicon|icon[-_.]|sprite|brand-?mark|placeholder|og-?default|default-?share/i.test(resolved)) return;
    seen.add(resolved);
    found.push({ url: resolved, tag });
  }
  const metaTags = htmlStr.match(/<meta\b[^>]*>/gi) || [];
  for (const tag of metaTags) {
    const propMatch = tag.match(/(?:property|name)\s*=\s*["']([^"']+)["']/i);
    const contentMatch = tag.match(/content\s*=\s*["']([^"']+)["']/i);
    if (!propMatch || !contentMatch) continue;
    const prop = propMatch[1].toLowerCase();
    if (['og:image', 'og:image:secure_url', 'og:image:url', 'twitter:image', 'twitter:image:src'].includes(prop)) {
      add(contentMatch[1], prop);
    }
  }
  return found.slice(0, 3);
}

for (const pick of picks) {
  try {
    const html = await this.helpers.httpRequest({
      method: 'GET',
      url: pick.url,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36' }
    });
    const htmlStr = String(html);

    try {
      const host = hostnameOf(pick.url).replace(/[^a-z0-9]/g, '');
      const source = (brandToken && host.includes(brandToken)) ? 'manufacturer_scrape' : 'editorial_scrape';
      for (const img of extractImages(htmlStr, pick.url)) {
        scrapedImages.push({ url: img.url, source, tag: img.tag, from_url: pick.url, is_primary: false });
      }
    } catch (e) { /* image extraction failing is never fatal to the research fetch */ }

    const cleaned = htmlStr
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;|&amp;|&quot;|&#39;/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    const text = extractRelevantWindow(cleaned, productName, 7000);
    pages.push({ category: pick.category, url: pick.url, why: pick.why, text });
  } catch (e) {
    pages.push({ category: pick.category, url: pick.url, why: pick.why, text: `[failed to fetch: ${e.message}]` });
  }
}

// Prefer a manufacturer-domain scrape over an editorial one if both turned up -
// marks the very first entry as primary so Source Product Photo can just take
// index 0 as the featured image without re-deriving this ordering itself.
scrapedImages.sort((a, b) => (a.source === 'manufacturer_scrape' ? 0 : 1) - (b.source === 'manufacturer_scrape' ? 0 : 1));
if (scrapedImages.length > 0) scrapedImages[0].is_primary = true;

return [{
  json: {
    ...item,
    fetched_pages: pages,
    verified_read_urls: pages.filter(p => !p.text.startsWith('[failed')).map(p => p.url),
    chosen_source_images: scrapedImages
  }
}];

const item = $input.item.json;

const extract_system_prompt = `You are a product research data extractor. You will be given the ACTUAL TEXT content of several real web pages that were already fetched for you (each labeled with its category and source_url), plus the product's name/brand/category.

Your job: extract ONLY real, verifiable evidence from the text you were given. Never invent facts, numbers, quotes, or URLs, and never use information not present in the provided page text. If a page's text looks like binary/garbage data (e.g. starts with %PDF or is unreadable symbols) or says "[failed to fetch...]", treat that category as having no usable evidence - return an empty array for it, do not guess.

Rules:
1. From the page(s) labeled 'specs', extract manufacturer_claim facts (ids FACT-001, FACT-002, ...).
2. From the page(s) labeled 'independent', extract independent_test findings (ids EXP-001, EXP-002, ...). If that page is actually about a closely related sibling/variant model rather than the exact product, say so explicitly in the source_name field.
3. From the page(s) labeled 'owner', extract owner_sentiment items (ids SENT-001, SENT-002, ...), each with topic/sentiment/detail.
4. From the page(s) labeled 'alternatives', extract 2-3 real alternative product names actually mentioned in that text, each with a one-sentence reason and using the given source_url.
5. Every item has exactly two source fields, and you must never mix them up:
   - "source_name": a short human-readable label, e.g. "ProductReview.com.au" or "Weber official website".
   - "source_url": the EXACT full URL given to you in that page's "SOURCE_URL:" label above (always starts with http:// or https://) - never put a domain name or description here, only the literal URL string you were given.
   Example of a correctly formatted item: {"id": "SENT-001", "topic": "durability", "sentiment": "negative", "detail": "...", "source_name": "ProductReview.com.au", "source_url": "https://www.productreview.com.au/listings/example"}
6. If a category's page text is empty, marked failed, unreadable, or has no relevant information, return an empty array for that category.
7. Do not fabricate anything not present in the given text.
8. Output JSON only, matching the required schema.`;

const pageBlocks = (item.fetched_pages || []).map(p =>
  `--- CATEGORY: ${p.category} | SOURCE_URL: ${p.url} ---\n${p.text}`
).join('\n\n');

const extract_user_prompt = `PRODUCT: ${JSON.stringify({ name: item.product_name, brand: item.brand, category: item.category })}

FETCHED PAGE CONTENT:
${pageBlocks}

Extract the structured research JSON from the above.`;

const research_schema = {"type": "object", "properties": {"product": {"type": "object", "properties": {"name": {"type": "string"}, "brand": {"type": "string"}, "category": {"type": "string"}, "model": {"type": "string"}}, "required": ["name", "brand", "category", "model"]}, "facts": {"type": "array", "items": {"type": "object", "properties": {"id": {"type": "string"}, "claim": {"type": "string"}, "source_name": {"type": "string"}, "source_url": {"type": "string"}, "type": {"type": "string", "enum": ["manufacturer_claim"]}}, "required": ["id", "claim", "source_name", "source_url", "type"]}}, "expert_findings": {"type": "array", "items": {"type": "object", "properties": {"id": {"type": "string"}, "finding": {"type": "string"}, "source_name": {"type": "string"}, "source_url": {"type": "string"}, "type": {"type": "string", "enum": ["independent_test"]}}, "required": ["id", "finding", "source_name", "source_url", "type"]}}, "owner_sentiment": {"type": "array", "items": {"type": "object", "properties": {"id": {"type": "string"}, "topic": {"type": "string"}, "sentiment": {"type": "string"}, "detail": {"type": "string"}, "source_name": {"type": "string"}, "source_url": {"type": "string"}}, "required": ["id", "topic", "sentiment", "detail", "source_name", "source_url"]}}, "alternatives": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "reason": {"type": "string"}, "source_url": {"type": "string"}}, "required": ["name", "reason", "source_url"]}}}, "required": ["product", "facts", "expert_findings", "owner_sentiment", "alternatives"]};

return [{
  json: {
    ...item,
    extract_system_prompt: extract_system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(research_schema)}`,
    extract_user_prompt,
    research_schema
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';
let research = null, parseError = null;
try { research = JSON.parse(raw); } catch (e) { parseError = e.message; }

const prep = $('Prepare Extract Prompt').item.json;

return [{
  json: {
    ollama_base_url: prep.ollama_base_url,
    writer_model: prep.writer_model,
    qa_model: prep.qa_model,
    qa_min_confidence: prep.qa_min_confidence,
    research,
    _parseOk: research !== null,
    _parseError: parseError,
    verified_read_urls: prep.verified_read_urls,
    _researchRetryCount: prep._researchRetryCount || 0
  }
}];

const item = $input.item.json;
const errors = [];

if (!item._parseOk || !item.research) {
  errors.push(`Research extraction output was not valid JSON: ${item._parseError}`);
  return [{ json: { ...item, _research_trust_valid: false, _research_trust_errors: errors } }];
}

const research = item.research;
const verifiedUrls = new Set(item.verified_read_urls || []);

function hostnameOf(url) {
  try { const m = String(url).match(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/(?:[^@/]+@)?([^/:?#]+)/); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; } catch (e) { return ''; }
}

const brandHost = hostnameOf((research.facts && research.facts[0] && research.facts[0].source_url) || '');

const allEvidence = [
  ...(research.facts || []),
  ...(research.expert_findings || []),
  ...(research.owner_sentiment || [])
];

for (const ev of allEvidence) {
  if (!ev.source_url) {
    errors.push(`Evidence ${ev.id} has no source_url`);
  } else if (!verifiedUrls.has(ev.source_url)) {
    errors.push(`Evidence ${ev.id} cites ${ev.source_url} but that page was never actually fetched - not acceptable evidence`);
  }
}

const independentReads = (research.expert_findings || []).filter(f =>
  f.type === 'independent_test' &&
  f.source_url && verifiedUrls.has(f.source_url) &&
  hostnameOf(f.source_url) !== brandHost
);

if (independentReads.length === 0) {
  errors.push('No genuinely independent (non-manufacturer-domain) expert finding was found AND actually fetched. At least one is required before this product can be reviewed.');
}

if (!research.alternatives || research.alternatives.length < 2) {
  errors.push('Research must include at least 2 real alternative products.');
}

return [{
  json: {
    ...item,
    _research_trust_valid: errors.length === 0,
    _research_trust_errors: errors
  }
}];

const item = $input.item.json;
const prep = $('Prepare Choose Prompt').item.json;

let priorPicks = [];
try { priorPicks = $('Parse Chosen URLs').item.json.picks || []; } catch (e) { priorPicks = []; }
const triedIndependentUrls = priorPicks.filter(p => p.category === 'independent').map(p => p.url);

const feedback = `\n\nYour previous source picks failed a trust check for these reasons:\n${(item._research_trust_errors || []).map(e => `- ${e}`).join('\n')}\n\nPick sources again. In particular:\n- Make sure the 'independent' pick's domain is genuinely different from the 'specs' pick's domain - do not reuse the same site for both categories.\n- Only pick URLs that are actually present in the given search results.${triedIndependentUrls.length ? `\n- These 'independent' URLs were already tried and did NOT yield usable independent review text (blocked, paywalled, membership-gated, or JS-only with no real article content): ${triedIndependentUrls.join(', ')}. Pick DIFFERENT 'independent' URL(s) this time - do not repeat any of them, even as a backup.` : ''}`;

return [{
  json: {
    ...prep,
    choose_user_prompt: prep.choose_user_prompt + feedback,
    _researchRetryCount: (item._researchRetryCount || 0) + 1
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';

let review = null;
let parseError = null;
try {
  review = JSON.parse(raw);
} catch (e) {
  parseError = e.message;
}

const prep = $('Prepare Prompts').item.json;

let retryCount = 0;
try {
  retryCount = $('Retry Writer').item.json._retryCount;
} catch (e) {
  retryCount = 0;
}

let qaRetryCount = 0;
try {
  qaRetryCount = $('Retry Writer After QA').item.json._qaRetryCount;
} catch (e) {
  qaRetryCount = 0;
}

return [{
  json: {
    review,
    _parseOk: review !== null,
    _parseError: parseError,
    research: prep.research,
    ollama_base_url: prep.ollama_base_url,
    writer_model: prep.writer_model,
    qa_model: prep.qa_model,
    qa_min_confidence: prep.qa_min_confidence,
    system_prompt: prep.system_prompt,
    user_prompt: prep.user_prompt,
    review_schema: prep.review_schema,
    qa_system_prompt: prep.qa_system_prompt,
    qa_schema: prep.qa_schema,
    _retryCount: retryCount,
    _qaRetryCount: qaRetryCount
  }
}];

const item = $input.item.json;
const errors = [];

if (!item._parseOk) {
  errors.push(`Writer output was not valid JSON: ${item._parseError}`);
}

const review = item.review;
const required = ["seo_title", "meta_description", "title", "summary", "pros", "cons", "verdict", "sections", "faq", "alternatives", "best_for", "not_best_for"];

if (review) {
  for (const field of required) {
    if (!(field in review)) errors.push(`Missing field: ${field}`);
  }
  if (review.pros && !Array.isArray(review.pros)) errors.push("pros must be an array");
  if (review.cons && !Array.isArray(review.cons)) errors.push("cons must be an array");
  if ("score" in review && typeof review.score !== "number") errors.push("score must be numeric");

  if (review.seo_title && review.seo_title.length > 60) {
    errors.push(`seo_title is ${review.seo_title.length} chars, must be 60 or fewer`);
  }
  if (review.meta_description && (review.meta_description.length > 160 || review.meta_description.length < 100)) {
    errors.push(`meta_description is ${review.meta_description.length} chars, must be roughly 100-160`);
  }
  if (Array.isArray(review.faq) && review.faq.length < 3) {
    errors.push(`faq has only ${review.faq.length} entries, need at least 3`);
  }
  if (Array.isArray(review.alternatives) && review.alternatives.length < 2) {
    errors.push(`alternatives has only ${review.alternatives.length} entries, need at least 2`);
  }

  const hedgePhrases = ["may want to consider", "could be a good option", "worth considering", "appears to be", "seems to be", "might be a good fit", "might be worth"];
  const verdictLower = (review.verdict || "").toLowerCase();
  for (const phrase of hedgePhrases) {
    if (verdictLower.includes(phrase)) {
      errors.push(`verdict uses hedging language ("${phrase}") instead of a decisive recommendation`);
    }
  }

  const validIds = new Set([
    ...item.research.facts.map(f => f.id),
    ...item.research.expert_findings.map(f => f.id),
    ...item.research.owner_sentiment.map(f => f.id)
  ]);

  if (Array.isArray(review.sections)) {
    for (const section of review.sections) {
      for (const evidenceId of (section.evidence_ids || [])) {
        if (!validIds.has(evidenceId)) {
          errors.push(`Section "${section.heading}" cites unknown evidence id: ${evidenceId}`);
        }
      }
    }
  }

  if (Array.isArray(review.faq)) {
    for (const qa of review.faq) {
      for (const evidenceId of (qa.evidence_ids || [])) {
        if (!validIds.has(evidenceId)) {
          errors.push(`FAQ "${qa.question}" cites unknown evidence id: ${evidenceId}`);
        }
      }
    }
  }

  if (Array.isArray(review.alternatives)) {
    const realNames = new Set((item.research.alternatives || []).map(a => a.name.toLowerCase()));
    for (const alt of review.alternatives) {
      if (!realNames.has((alt.name || "").toLowerCase())) {
        errors.push(`Alternative "${alt.name}" is not in the supplied research alternatives list (possibly invented)`);
      }
    }
  }
}

return [{
  json: {
    ...item,
    _valid: errors.length === 0,
    _errors: errors
  }
}];

const item = $input.item.json;

const feedback = `\n\nYour previous output failed validation for these reasons:\n${item._errors.map(e => `- ${e}`).join('\n')}\n\nFix these issues and return corrected JSON that strictly matches the schema and only cites evidence ids that were supplied.`;

return [{
  json: {
    ollama_base_url: item.ollama_base_url,
    writer_model: item.writer_model,
    qa_model: item.qa_model,
    qa_min_confidence: item.qa_min_confidence,
    system_prompt: item.system_prompt,
    user_prompt: item.user_prompt + feedback,
    review_schema: item.review_schema,
    qa_system_prompt: item.qa_system_prompt,
    qa_schema: item.qa_schema,
    research: item.research,
    _retryCount: (item._retryCount || 0) + 1
  }
}];

const item = $input.item.json;

const qa_user_prompt = `REVIEW TO CHECK:\n${JSON.stringify(item.review)}\n\nSUPPLIED EVIDENCE:\n${JSON.stringify(item.research)}\n\nCheck the review above against the supplied evidence and return your JSON verdict.`;

return [{
  json: {
    ollama_base_url: item.ollama_base_url,
    qa_model: item.qa_model,
    qa_system_prompt: item.qa_system_prompt,
    qa_user_prompt,
    qa_schema: item.qa_schema,
    qa_min_confidence: item.qa_min_confidence,
    review: item.review,
    research: item.research,
    _qaRetryCount: item._qaRetryCount
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';

let qa = null;
let parseError = null;
try {
  qa = JSON.parse(raw);
} catch (e) {
  parseError = e.message;
}

const prep = $('Prepare QA Prompt').item.json;

return [{
  json: {
    qa,
    _qaParseOk: qa !== null,
    _qaParseError: parseError,
    review: prep.review,
    research: prep.research,
    qa_min_confidence: prep.qa_min_confidence,
    ollama_base_url: prep.ollama_base_url,
    qa_model: prep.qa_model,
    writer_model: $('Parse Writer JSON').item.json.writer_model,
