const firstKwWord = kw.split(/\s+/)[0] || '';

const checks = [];
function check(name, passed, detail) { checks.push({ name, passed: !!passed, detail: detail || '' }); }

check('seo_title_present', title.length > 0);
check('seo_title_length', title.length > 0 && title.length <= 60, `${title.length} chars (target <=60)`);
