// Third priority (was: Openverse CC-licensed keyword search). Openverse indexes
// CC-licensed stock/wiki media, not official product photography - an exact
// "Brand Model Number" query routinely returns zero results for anything recent
// (confirmed live: "Apple AirPods Pro 3" -> 0 results). Replaced 2026-09-23 with
// an agentic OpenRouter search: a tool-calling model actually searches SearxNG,
// opens candidate pages, and verifies relevance itself instead of a fixed
// keyword-tier + tag-matching heuristic - confirmed live to find real
// manufacturer/retailer photos (Sony WH-1000XM6, Dyson V8 Animal) that the old
// Openverse tier had no chance of returning.
//
// Same false-match risk the old tier guarded against still applies (a brand name
// can collide with unrelated things - "Sony" also makes cameras, "Anker" is also
// a historical person's surname) - the agent's system prompt is told this
// explicitly. Two extra safety nets on top of the model's own judgement:
// (1) grounding - a selected image_url is only trusted if it literally appeared
// in a search_images/fetch_page tool result during this conversation, so the
// model can't just recall a plausible-looking URL from training data; (2) live
// verification - every grounded candidate gets a real HTTP fetch to confirm it
// resolves to an actual image before being trusted.
const OPENROUTER_MODEL = 'openai/gpt-4o-mini';
const SEARXNG_URL = 'http://searxng:8080/search';
const MAX_TOOL_STEPS = 8;

function resolveImgUrl(url, base) {
  if (!url) return null;
  url = String(url).trim();
  if (/^https?:\/\//i.test(url)) return url;
  const schemeMatch = String(base).match(/^([a-zA-Z][a-zA-Z0-9+.-]*:)/);
  const scheme = schemeMatch ? schemeMatch[1] : 'https:';
  if (/^\/\//.test(url)) return scheme + url;
  const originMatch = String(base).match(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^/]+/);
  const origin = originMatch ? originMatch[0] : '';
  if (url.startsWith('/')) return origin + url;
  const basePath = String(base).replace(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^/]+/, '').replace(/[^/]*$/, '');
  return origin + basePath + url;
}

async function agenticSearchImages(query) {
  const res = await this.helpers.httpRequest({ method: 'GET', url: SEARXNG_URL, qs: { q: query, format: 'json', categories: 'images' }, json: true });
  return ((res && res.results) || []).slice(0, 8).map(r => ({ page_url: r.url, image_url: r.img_src, title: r.title, source: r.engine }));
}
async function agenticSearchWeb(query) {
  const res = await this.helpers.httpRequest({ method: 'GET', url: SEARXNG_URL, qs: { q: query, format: 'json', categories: 'general' }, json: true });
  return ((res && res.results) || []).slice(0, 8).map(r => ({ url: r.url, title: r.title, snippet: r.content }));
}
async function agenticFetchPage(pageUrl) {
  let html;
  try {
    html = await this.helpers.httpRequest({ method: 'GET', url: pageUrl, headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36' } });
  } catch (e) {
    return { page_url: pageUrl, error: e.message, images: [] };
  }
  const htmlStr = String(html);
  const found = [];
  const metaTags = htmlStr.match(/<meta\b[^>]*>/gi) || [];
  for (const tag of metaTags) {
    const propMatch = tag.match(/(?:property|name)\s*=\s*["']([^"']+)["']/i);
    const contentMatch = tag.match(/content\s*=\s*["']([^"']+)["']/i);
    if (!propMatch || !contentMatch) continue;
    const prop = propMatch[1].toLowerCase();
    if (['og:image', 'og:image:secure_url', 'twitter:image', 'twitter:image:src'].includes(prop)) {
      const resolved = resolveImgUrl(contentMatch[1], pageUrl);
      if (resolved) found.push({ url: resolved, tag: prop });
    }
  }
  const titleMatch = htmlStr.match(/<title[^>]*>([^<]+)<\/title>/i);
  return { page_url: pageUrl, title: titleMatch ? titleMatch[1].trim() : null, images: found.slice(0, 5) };
}
async function agenticVerifyImageUrl(url) {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url, headers: { Range: 'bytes=0-2048' }, returnFullResponse: true, encoding: 'arraybuffer' });
    const ct = (res.headers['content-type'] || res.headers['Content-Type'] || '').toString();
    return res.statusCode < 400 && ct.startsWith('image/');
  } catch (e) { return false; }
}

const agenticTools = [
  { type: 'function', function: { name: 'search_images', description: 'Search the web for images matching a query. Returns candidate image URLs with the page they came from.', parameters: { type: 'object', properties: { query: { type: 'string' } }, required: ['query'] } } },
  { type: 'function', function: { name: 'search_web', description: 'General web search (not image-specific). Use to find the manufacturer/retailer product page.', parameters: { type: 'object', properties: { query: { type: 'string' } }, required: ['query'] } } },
  { type: 'function', function: { name: 'fetch_page', description: 'Fetch a page and extract its title plus og:image/twitter:image meta tags. Use to verify a product page and pull its real photo.', parameters: { type: 'object', properties: { url: { type: 'string' } }, required: ['url'] } } },
  { type: 'function', function: { name: 'select_images', description: 'Final answer: up to 3 distinct real photos of this exact product (different angles or listings), ranked best first.', parameters: { type: 'object', properties: { images: { type: 'array', minItems: 1, maxItems: 3, items: { type: 'object', properties: { image_url: { type: 'string' }, source_page_url: { type: 'string' }, credit: { type: 'string' }, reason: { type: 'string' } }, required: ['image_url', 'reason'] } } }, required: ['images'] } } }
];

async function agenticRunTool(name, args) {
  if (name === 'search_images') return agenticSearchImages.call(this, args.query);
  if (name === 'search_web') return agenticSearchWeb.call(this, args.query);
  if (name === 'fetch_page') return agenticFetchPage.call(this, args.url);
  throw new Error('unknown tool ' + name);
}

async function agenticCallOpenRouter(messages, forceSelect) {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: { Authorization: `Bearer ${$env.OPENROUTER_API_KEY}`, 'Content-Type': 'application/json' },
    body: { model: OPENROUTER_MODEL, messages, tools: agenticTools, tool_choice: forceSelect ? { type: 'function', function: { name: 'select_images' } } : 'auto' },
    json: true
  });
  return res.choices[0].message;
}

async function agenticSourcePhotos(brand, name, category) {
  const messages = [
    {
      role: 'system',
      content: `You are a product-photo research agent for an affiliate review website. Given a product (brand, name, category), find up to 3 DISTINCT real, accurate photos of that exact product (different angles, colorways, or listings - not the same image twice) using the tools available (search_images, search_web, fetch_page). Prefer official manufacturer or major retailer photos over random stock/wiki images. It is fine to return fewer than 3 if you cannot confirm more.

Be careful of false matches: a brand name can collide with unrelated things (e.g. "Sony" also makes cameras, "Anker" is also a historical person's surname) - verify each image/page is actually about THIS product before selecting it. Avoid logos, placeholder icons, and unrelated lifestyle photos.

CRITICAL: you may ONLY select an image_url that was literally returned to you in a search_images or fetch_page tool result during this conversation. Never invent or recall a URL from memory - if you haven't seen it in a tool result this session, it doesn't count as found.

You have a limited number of tool calls. Use search_images and/or search_web to gather multiple candidates, then fetch_page on the most promising ones to confirm before calling select_images with your final ranked list.`
    },
    { role: 'user', content: `Find up to 3 real product photos for: ${brand || ''} ${name || ''} (category: ${category || ''}).` }
  ];

  const groundedUrls = new Set();
  function ground(urls) { for (const u of urls) if (u) groundedUrls.add(u); }
  let finalImages = null;

  for (let step = 0; step < MAX_TOOL_STEPS && !finalImages; step++) {
    const forceSelect = step === MAX_TOOL_STEPS - 1;
    const msg = await agenticCallOpenRouter.call(this, messages, forceSelect);
    messages.push(msg);
    if (!msg.tool_calls || msg.tool_calls.length === 0) continue;

    for (const tc of msg.tool_calls) {
      const args = JSON.parse(tc.function.arguments || '{}');
      if (tc.function.name === 'select_images') {
        const candidates = (args.images || []).filter(i => i && i.image_url).slice(0, 3);
        const grounded = candidates.filter(c => groundedUrls.has(c.image_url));
        if (!grounded.length) {
          messages.push({ role: 'tool', tool_call_id: tc.id, content: JSON.stringify({ error: 'None of those image_urls appeared in a prior tool result. Search again and only select URLs you actually saw in a tool result.' }) });
          break;
        }
        const verified = [];
        for (const c of grounded) { if (await agenticVerifyImageUrl.call(this, c.image_url)) verified.push(c); }
        finalImages = verified;
        break;
      }
      let result;
      try { result = await agenticRunTool.call(this, tc.function.name, args); }
      catch (e) { result = { error: e.message }; }
      if (Array.isArray(result)) ground(result.map(r => r.image_url).filter(Boolean));
      else if (result && result.images) ground(result.images.map(im => im.url).filter(Boolean));
      messages.push({ role: 'tool', tool_call_id: tc.id, content: JSON.stringify(result) });
    }
  }
  return finalImages || [];
}

