// actually own outright, no licensing question at all, unlike every scraped/
// Openverse photo elsewhere in this pipeline. Deliberately NOT asked to depict
// the real device: generative models can't reliably reproduce an exact product's
// design/logo (same lesson as the Openverse relevance work - an inaccurate fake
// render of a real product would undermine reader trust more than no banner at
// all), so the prompt asks for an abstract/editorial mood piece instead, with an
// explicit no-logos/no-text instruction to avoid a garbled trademark lookalike.
const prompt = `Create a wide, modern editorial-style decorative banner illustration for a tech product review website. Theme: ${category}. Style: clean, abstract, soft gradient background, tasteful minimalist composition that evokes the product category's mood without depicting any specific real device, brand logo, or readable text anywhere in the image. Aspect ratio 16:9, high quality, professional editorial tech-blog aesthetic.`;

let heroBannerBase64 = null, heroBannerMime = null;
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-image:generateContent?key=${$env.GEMINI_API_KEY}`,
    headers: { 'Content-Type': 'application/json' },
    body: { contents: [{ parts: [{ text: prompt }] }] },
    json: true,
    timeout: 60000
  });
  const parts = (res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts) || [];
  const imagePart = parts.find(p => p.inlineData && p.inlineData.data);
  if (imagePart) {
    heroBannerBase64 = imagePart.inlineData.data;
    heroBannerMime = imagePart.inlineData.mimeType || 'image/png';
  }
} catch (e) {
  // Purely decorative - never fatal. The post publishes fine without a banner.
}

